window.DEX_DATA["sources:backport-e65c55543614f794"]={"json":{"skins":[{"filename":"shopman.png"}],"names":[{"name":"斯帕兹先生"},{"name":"杂货商吉尔"},{"name":"佩尼先生"},{"name":"仓管伯特"},{"name":"格林先生"}],"chat":[{"lines":[{"text":"你好，要买些新鲜西兰花吗？"},{"text":"你不喜欢西兰花？这还真是头一次听说！"}]},{"lines":[{"text":"欢迎来到市场，我帮你找找想买的东西？"},{"text":"宝可梦？不，这里是食品市场，你应该不吃那个吧？"}]},{"lines":[{"text":"今天天气不错，要买几根香蕉吗？"},{"text":"香蕉能健脑，所以我才这么聪明！"}]},{"lines":[{"text":"快来快来！今天店里全是好价钱！"},{"text":"太贵？哈！比起昨天的价格，已经很便宜啦！"}]},{"lines":[{"text":"今天刚到了一批又甜又好的苹果。"},{"text":"不可以先尝后买！"}]}]}};
